style.css:
@-moz-document url-prefix("https://docs.google.com/document/") {
/* Main editor background */
  .kix-appview-editor {
    background-image: url("https://static0.gamerantimages.com/wordpress/wp-content/uploads/2025/02/shadow-milk-cookie-cookie-run-kingdom.jpg") !important;
    background-attachment: fixed !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-color: #0a0a0a !important; /* dark fallback */
  }

  /* Top chrome / header area background */
  #docs-chrome {
    background-image: url("https://static0.gamerantimages.com/wordpress/wp-content/uploads/2025/02/shadow-milk-cookie-cookie-run-kingdom.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
  }

  /* Rulers */
  #kix-vertical-ruler,
  #kix-horizontal-ruler-container {
    background-image: url("https://static0.gamerantimages.com/wordpress/wp-content/uploads/2025/02/shadow-milk-cookie-cookie-run-kingdom.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    opacity: 0.5 !important;
  }

  #kix-vertical-ruler .docs-ruler-mask,
  #kix-horizontal-ruler .docs-ruler-mask {
    opacity: 0.35 !important;
  }

  /* Canvas / page content opacity */
  .kix-page-paginated > .kix-canvas-tile-content {
    opacity: 0.60 !important;
  }

  /* Toolbar & menus */
  #docs-menubars,
  #docs-toolbar-wrapper {
    opacity: 0.50 !important;
    background-color: rgba(10, 10, 20, 0.85) !important; /* subtle dark overlay */
  }

  /* Omnibox (search) */
  .docs-omnibox-input {
    opacity: 0.35 !important;
  }

  /* Navigation / side panel */
  .navigation-widget {
    opacity: 0.75 !important;
  }

  /* Title bar buttons */
  .docs-titlebar-buttons {
    background-color: #000080 !important; /* darkblue */
    color: white !important;
    opacity: 0.35 !important;
  }

  /* Document title text */
  #docs-title-input-label-inner {
    color: white !important;
  }

  /* Menu text color */
  #docs-file-menu,
  #docs-edit-menu,
  #docs-view-menu,
  #docs-insert-menu,
  #docs-format-menu,
  #docs-tools-menu,
  #docs-extensions-menu,
  #docs-help-menu {
    color: white !important;
  }
}
